"""Visual contract generated by executing semi-utils b1cf1ce standard1."""

from pathlib import Path

import cv2
import numpy as np
import pytest
from PIL import Image

from ccraw import watermark

FIXTURES = Path(__file__).parent / 'fixtures' / 'watermark-standard1'
PHOTO = dict(
    body='EOS R6',
    lens='RF 35mm F1.8',
    focal='35 mm',
    aperture='f/2.8',
    shutter='1/500 s',
    iso='ISO 800',
    date='2025-07-12 18:05:06',
    brand='Canon',
)


@pytest.mark.parametrize(
    'width,height,brand', [(1600, 1067, 'canon'), (1100, 1600, 'nikon'), (1920, 640, 'sony')]
)
def test_standard1_footer_matches_executed_upstream(width, height, brand):
    settings = dict(
        watermark.defaults(),
        enabled=True,
        template='standard1',
        pipeline=watermark.template_pipeline('standard1'),
    )
    rgb = np.full((height, width, 3), 0.37123, np.float32)
    output = watermark.apply(rgb, settings, dict(PHOTO, brand=brand))
    expected = np.asarray(Image.open(FIXTURES / f'{width}x{height}-{brand}.png'))
    actual = np.rint(output[height:] * 255).astype(np.uint8)
    assert actual.shape == expected.shape
    np.testing.assert_array_equal(actual, expected)
    np.testing.assert_array_equal(output[:height], rgb)


def test_preview_downsamples_final_layout_instead_of_retypesetting():
    settings = dict(
        watermark.defaults(),
        enabled=True,
        template='standard1',
        pipeline=watermark.template_pipeline('standard1'),
    )
    rgb = np.full((1067, 1600, 3), 0.37123, np.float32)
    exported = watermark.apply(rgb, settings, PHOTO)
    expected = cv2.resize(exported, (500, 373), interpolation=cv2.INTER_AREA)
    actual = watermark.preview(rgb, settings, PHOTO, limit=500)
    assert actual.shape == expected.shape
    np.testing.assert_allclose(actual, expected, atol=2e-6)


def test_standard1_portrait_footer_is_twelve_percent_of_height():
    settings = dict(
        watermark.defaults(),
        enabled=True,
        template='standard1',
        pipeline=watermark.template_pipeline('standard1'),
    )
    assert watermark.dimensions((1600, 1100, 3), settings) == (1100, 1792)


@pytest.mark.parametrize(
    'margins',
    [
        dict(left_margin=25, right_margin=25, top_margin=25, bottom_margin=25),
        dict(top_margin=11, bottom_margin=29, left_margin=17),
    ],
)
def test_preview_pipeline_margins_matches_final_export_filter(margins):
    rgb = np.random.default_rng(13).random((137, 211, 3), dtype=np.float32)
    settings = dict(
        watermark.defaults(),
        enabled=True,
        pipeline=[dict(processor_name='margin', margin_color='white', **margins)],
    )
    exported = watermark.apply(rgb, settings, PHOTO)
    ratio = 97 / max(exported.shape[:2])
    size = (round(exported.shape[1] * ratio), round(exported.shape[0] * ratio))
    expected = cv2.resize(exported, size, interpolation=cv2.INTER_AREA)
    np.testing.assert_allclose(
        watermark.preview(rgb, settings, PHOTO, limit=97), expected, atol=2e-6
    )


def test_null_metadata_omits_the_same_content_as_empty_metadata():
    settings = dict(
        watermark.defaults(),
        enabled=True,
        template='standard1',
        pipeline=watermark.template_pipeline('standard1'),
    )
    rgb = np.zeros((1000, 1600, 3), np.float32)
    empty = watermark.apply(rgb, settings, {})
    null = watermark.apply(rgb, settings, {key: None for key in PHOTO})
    np.testing.assert_array_equal(null, empty)


def test_proxy_preview_keeps_final_footer_layout(monkeypatch):
    settings = dict(
        watermark.defaults(),
        enabled=True,
        template='standard1',
        pipeline=watermark.template_pipeline('standard1'),
    )
    # The camera proxy is only 160px wide; typography must use the 1600px export.
    proxy = np.full((107, 160, 3), 0.37123, np.float32)
    photo = np.full((1067, 1600, 3), 0.37123, np.float32)
    # The PNG goldens verify 8-bit upstream appearance. Preview integrates the
    # actual float export, including unquantized decoration alpha blending.
    exported = watermark.apply(photo, settings, PHOTO)
    expected = cv2.resize(exported, (500, 373), interpolation=cv2.INTER_AREA)

    def forbid_full_photo_allocation(*args, **kwargs):
        raise AssertionError('preview allocated the full bordered photo')

    monkeypatch.setattr(watermark, 'apply', forbid_full_photo_allocation)
    preview = watermark.preview(proxy, settings, PHOTO, limit=500, final_shape=(1067, 1600, 3))
    np.testing.assert_allclose(preview, expected, atol=2e-6)
